    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        if isinstance(v, dict) and "meta" in v:
            seq = int(v["meta"].get("seq", 0))
            continue
        for o in (v if isinstance(v, list) else [v]):
            kind = (o.get("kind") or "new").lower()
            typ = {"amend": "C", "void": "V"}.get(kind, "N")
            num = sid(str(o.get("id")))
            if typ == "V":
                out.append(rec(num, "V", None, None, None))
                continue
            kg = None
            for key, val in o.items():
                m = re.fullmatch(r"weight_(kg|g|lb|oz)", key)
                if m:
                    kg = qty(str(val), m[1])
            out.append(rec(num, typ, to_date(o["shipped_at"]), kg, norm_status(o["status"])))
    return seq, out


def p_river(text):
