            if m:
                fmt = m[1].upper()
            m = re.match(r"#\s*weight unit\s*:\s*(\w+)", r, re.I)
            if m:
                unit = m[1].lower()
            continue
        if [c.strip().lower() for c in r][:2] == ["t", "ref"]:
            cols = [c.strip().lower() for c in r]
            continue
        if cols is None:
            continue
        d = dict(zip(cols, r))
        typ = {"C": "C", "V": "V"}.get(d.get("t", "").strip().upper(), "N")
        num = sid(d["ref"])
        if num is None:
            continue
