            continue
        d = dict(zip(cols, r))
        typ = d.get("typ", "N").strip().upper() or "N"
        num = sid(d["id"])
        if num is None:
            continue
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        w = d["weight"].strip().replace(".", "").replace(",", ".")
        out.append(rec(num, typ, to_date(d["shipped"], "DMY"), qty(w, unit), norm_status(d["status"])))
    return seq, out


