def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        raw = open(path, "rb").read()
        if raw[:2] == b"\x1f\x8b":
            raw = gzip.decompress(raw)
        if depot == "central":
            seq, recs = p_central(raw)
        else:
            seq, recs = PARSERS[depot](decode(raw))
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = current[depot] = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["id"]
                if r["type"] == "N":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "C":
                    cur[n] = r
                    corrections += 1
                elif r["type"] == "V":
                    cur.pop(n, None)
                    corrections += 1

    order = sorted(current, key=lambda d: PRIORITY.index(d) if d in PRIORITY else len(PRIORITY))
    kept, seen_in = {}, {}
    for depot in order:
        for n, r in current[depot].items():
            seen_in[n] = seen_in.get(n, 0) + 1
            if n not in kept:
                kept[n] = (depot, r)
    handovers = sum(1 for c in seen_in.values() if c > 1)

    dep = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for n, (depot, r) in kept.items():
        if r["status"] not in COUNTED:
            continue
        dep[depot][0] += 1
        dep[depot][1] += r["kg"]
        m = months.setdefault("%04d-%02d" % (r["date"].year, r["date"].month), [0, Fraction(0)])
        m[0] += 1
        m[1] += r["kg"]

    def rnd(x):
        d = Decimal(x.numerator) / Decimal(x.denominator)
        return float(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    res = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd(v[1])} for d, v in dep.items()},
        "months": {k: {"shipments": v[0], "total_kg": rnd(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(res, fh, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
