        d = dict(zip(cols, r))
        typ = {"NEW": "N", "COR": "C", "VOID": "V"}[d["rec"].strip().upper()]
        num = sid(d["ref"])
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        n, u = d["weight"].split()
        st = d["state"].strip().upper()
        out.append(rec(num, typ, to_date(d["date"]), qty(n, u), HSTATE.get(st, norm_status(st))))
    return seq, out


def p_lakeside(text):
    seq, mode, cols, out = 0, "iso", None, []
    for k, r in csv_rows(text, ","):
        if k == "c":
            m = re.match(r"#\s*seq\s*:\s*(\d+)", r, re.I)
            if m and not seq:
                seq = int(m[1])
            m = re.match(r"#\s*dates\s*:\s*(\w+)", r, re.I)
            if m:
                mode = m[1].lower()
            continue
        if is_header(r):
            cols = [c.strip().lower() for c in r]
            continue
        if cols is None:
            continue
        d = dict(zip(cols, r))
        kind = d.get("kind", "").strip().lower()
        typ = {"corr": "C", "void": "V"}.get(kind, "N")
        num = sid(d["id"])
        if num is None:
            continue
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        out.append(rec(num, typ, to_date(d["shipped"], "serial" if mode == "serial" else None),
                       qty(d["gross_kg"].strip(), "kg"), norm_status(d["status"])))
    return seq, out


def p_north(text):
    seq, out = 0, []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        if isinstance(v, dict) and "meta" in v:
            seq = int(v["meta"].get("seq", 0))
            continue
        for o in (v if isinstance(v, list) else [v]):
            kind = (o.get("kind") or "new").lower()
            typ = {"amend": "C", "void": "V"}.get(kind, "N")
            num = sid(str(o.get("id")))
            if typ == "V":
                out.append(rec(num, "V", None, None, None))
                continue
            kg = None
            for key, val in o.items():
                m = re.fullmatch(r"weight_(kg|g|lb|oz)", key)
                if m:
                    kg = qty(str(val), m[1])
            out.append(rec(num, typ, to_date(o["shipped_at"]), kg, norm_status(o["status"])))
    return seq, out


def p_river(text):
    seq, fmt, unit, cols, out = 0, "MM/DD/YYYY", "g", None, []
    for k, r in csv_rows(text, "\t"):
        if k == "c":
            m = re.match(r"#\s*seq\s*:\s*(\d+)", r, re.I)
            if m and not seq:
                seq = int(m[1])
            m = re.match(r"#\s*date format\s*:\s*(\S+)", r, re.I)
            if m:
                fmt = m[1].upper()
            m = re.match(r"#\s*weight unit\s*:\s*(\w+)", r, re.I)
            if m:
                unit = m[1].lower()
            continue
        if [c.strip().lower() for c in r][:2] == ["t", "ref"]:
            cols = [c.strip().lower() for c in r]
            continue
        if cols is None:
            continue
        d = dict(zip(cols, r))
        typ = {"C": "C", "V": "V"}.get(d.get("t", "").strip().upper(), "N")
        num = sid(d["ref"])
        if num is None:
            continue
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        out.append(rec(num, typ, to_date(d["shipped"], "DMY" if fmt.startswith("DD") else "MDY"),
                       qty(d["weight"].strip(), unit), norm_status(d["status"])))
    return seq, out


LAYOUTS = {
    "FW1": dict(id=(1, 9), type=(10, 10), shipped=(11, 17), weight=(18, 25), status=(26, 26),
                doy=True, unit=Fraction(1, 1000)),
    "FW2": dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27),
                doy=False, unit=Fraction(1, 100)),
    "FW3": dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25),
                doy=True, unit=Fraction(1, 10) * KG["lb"]),
}
SSTATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


def p_south(text):
    seq, lay, out = 0, None, []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or line.lstrip().upper().startswith("SOUTH DEPOT"):
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line)
            if m:
                lay = LAYOUTS[m[1].upper()]
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and not seq:
                seq = int(m[1])
            continue
        if not line.strip() or lay is None:
            continue

        def f(n):
            a, b = lay[n]
            return line[a - 1:b]
        typ = f("type").strip().upper()
        num = sid(f("id"))
        if num is None:
            continue
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        s = f("shipped").strip()
        if lay["doy"]:
            d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            d = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        out.append(rec(num, typ, d, int(f("weight")) * lay["unit"] if lay["unit"] != KG["lb"] / 10
                       else int(f("weight")) * lay["unit"],
                       SSTATUS.get(f("status").strip().upper(), "")))
    return seq, out


def p_west(text):
    seq, unit, cols, out = 0, "lb", None, []
    for k, r in csv_rows(text, ";"):
        if k == "c":
            m = re.match(r"#\s*seq\s*:\s*(\d+)", r, re.I)
            if m and not seq:
                seq = int(m[1])
            m = re.match(r"#\s*weight unit\s*:\s*(\w+)", r, re.I)
            if m:
                unit = m[1].lower()
            continue
        if is_header(r):
            cols = [c.strip().lower() for c in r]
            continue
        if cols is None:
            continue
        d = dict(zip(cols, r))
        typ = d.get("typ", "N").strip().upper() or "N"
        num = sid(d["id"])
        if num is None:
            continue
        if typ == "V":
            out.append(rec(num, "V", None, None, None))
            continue
        w = d["weight"].strip().replace(".", "").replace(",", ".")
        out.append(rec(num, typ, to_date(d["shipped"], "DMY"), qty(w, unit), norm_status(d["status"])))
    return seq, out


PARSERS = {"east": p_east, "harbor": p_harbor, "lakeside": p_lakeside, "north": p_north,
           "river": p_river, "south": p_south, "west": p_west}


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        raw = open(path, "rb").read()
        if raw[:2] == b"\x1f\x8b":
            raw = gzip.decompress(raw)
        if depot == "central":
            seq, recs = p_central(raw)
        else:
            seq, recs = PARSERS[depot](decode(raw))
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = current[depot] = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["id"]
                if r["type"] == "N":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "C":
                    cur[n] = r
                    corrections += 1
                elif r["type"] == "V":
                    cur.pop(n, None)
                    corrections += 1

    order = sorted(current, key=lambda d: PRIORITY.index(d) if d in PRIORITY else len(PRIORITY))
    kept, seen_in = {}, {}
    for depot in order:
        for n, r in current[depot].items():
            seen_in[n] = seen_in.get(n, 0) + 1
            if n not in kept:
                kept[n] = (depot, r)
    handovers = sum(1 for c in seen_in.values() if c > 1)

    dep = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for n, (depot, r) in kept.items():
        if r["status"] not in COUNTED:
            continue
        dep[depot][0] += 1
        dep[depot][1] += r["kg"]
        m = months.setdefault("%04d-%02d" % (r["date"].year, r["date"].month), [0, Fraction(0)])
        m[0] += 1
        m[1] += r["kg"]

    def rnd(x):
        d = Decimal(x.numerator) / Decimal(x.denominator)
        return float(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    res = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd(v[1])} for d, v in dep.items()},
        "months": {k: {"shipments": v[0], "total_kg": rnd(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(res, fh, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
